#include "../upstream/gframe/card_download.h"
#include <iostream>
#include <chrono>
#include <fstream>
using namespace ygo;
int main(int argc,char** argv){try{std::atomic<bool> cancel{false};std::string url="https://cdntx.moecube.com/ygopro-super-pre/archive/ygopro-super-pre-29.13.ypk";unsigned maxConnections=0;bool cached=false,progressSeen=false;if(argc>3 && std::string(argv[3])=="resume"){
 bool stopped=false;try{CardDownload::Cached(url,argv[1],[&](const CardDownloadProgress& p){if(p.downloaded>5*1024*1024 && !p.cached)cancel=true;},cancel);}catch(...){stopped=cancel.load();}if(!stopped)throw std::runtime_error("Cancellation did not stop the download");cancel=false;bool reused=false;auto resumed=CardDownload::Cached(url,argv[1],[&](const CardDownloadProgress& p){reused|=p.resumed>0;},cancel);if(!reused)throw std::runtime_error("No completed segment was reused");std::ofstream resumedFile(argv[2],std::ios::binary);resumedFile.write(reinterpret_cast<const char*>(resumed.data()),resumed.size());std::cout<<"PASS cancelled transfer preserves validated segments and resumes without redownloading them"<<std::endl;return 0;
 }
auto start=std::chrono::steady_clock::now();auto bytes=CardDownload::Cached(url,argv[1],[&](const CardDownloadProgress& p){maxConnections=std::max(maxConnections,p.connections);cached|=p.cached;progressSeen|=p.total>0 && p.downloaded>0 && p.downloaded<p.total;},cancel);auto elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::cout<<"TRANSFER bytes="<<bytes.size()<<" seconds="<<elapsed<<" max_connections="<<maxConnections<<" cached="<<cached<<" visible_progress="<<progressSeen<<std::endl;bool cacheAgain=false;auto second=CardDownload::Cached(url,argv[1],[&](const CardDownloadProgress& p){cacheAgain|=p.cached;},cancel);if(bytes!=second || !cacheAgain)throw std::runtime_error("Validated cache was not reused");if(!cached && (!progressSeen || maxConnections<2))throw std::runtime_error("Parallel transfer did not report measurable progress");std::ofstream out(argv[2],std::ios::binary);out.write(reinterpret_cast<const char*>(bytes.data()),bytes.size());std::cout<<"PASS range download and byte-identical cache reuse"<<std::endl;return 0;}catch(const std::exception& e){std::cerr<<e.what()<<std::endl;return 1;}}
